import json,re
def _first_s(text):
    t=(text or "").strip(); m=re.search(r'[。！？\n]', t)
    return t[:m.start()].strip() if m and m.start()>=10 else t[:60]
def _md_hs(text):
    hs,seen=[],set()
    for line in text.split('\n'):
        m=re.match(r'(#{1,3})\s+(.+)', line.strip())
        if m:
            h=m.group(2).strip()
            if h not in seen: seen.add(h); hs.append(h)
    return hs[:4]
def _snips(text,kws,ctx=40):
    tl=(text or "").lower()
    if not tl or not kws: return ""
    seen,parts=set(),[]
    for k in kws:
        pos=tl.find(k.lower())
        if pos<0 or pos in seen: continue
        seen.add(pos)
        s=max(0,pos-ctx); e=min(len(text),pos+len(k)+ctx)
        frag=text[s:e]
        if s>0: frag="…"+frag
        if e<len(text): frag+="…"
        parts.append(frag)
        if len(parts)>=3: break
    return " | ".join(parts) if parts else ""

async def main(args) -> dict:
    history = args.params.get("history") or []
    kws = args.params.get("keywords") or []
    sem = args.params.get("semantic_hits") or []
    cands = []
    # 语义结果直接作为候选（score乘3拉平与keyword分尺度）
    for s in sem:
        tidx = s.get("turn_idx",0)
        score = float(s.get("score",0)) * 3
        text = s.get("text","") or f"(语义命中 第{tidx}轮)"
        cands.append({"kind":"semantic","turn_idx":tidx,"text":text,"score":score})
    if not kws and not history: return {"candidates":cands}
    kl = [k.lower() for k in kws]
    for item in reversed(history):
        tidx = item.get("turn",0)
        u = item.get("user","") or ""; a = item.get("answer","") or ""
        ul=u.lower(); al=a.lower()
        hu=[k for k in kl if k in ul]; ha=[k for k in kl if k in al]
        if hu or ha:
            parts=[]
            us=_snips(u,hu) or u[:60]
            if us: parts.append(f"用户: {us}")
            if hu: parts.append(f"命中: {', '.join(hu)}")
            fs=_first_s(a)
            if fs: parts.append(f"回答: {fs}")
            sa=_snips(a,ha)
            if sa and sa!=fs: parts.append(f"回答(命中): {sa}")
            hs=_md_hs(a)
            if hs: parts.append(f"章节: {' > '.join(hs)}")
            cands.append({"kind":"turn","turn_idx":tidx,"text":" | ".join(parts),"score":len(hu)+len(ha)})
        for step in item.get("steps",[]):
            for tc in step.get("tool_calls",[]):
                name_full = tc.get("name","") or ""
                args_full = json.dumps(tc.get("arguments"),ensure_ascii=False)
                result_full = tc.get("result","") or ""
                n=name_full.lower(); ar=args_full.lower(); rt=result_full.lower()
                hk=[k for k in kl if k in n or k in ar or k in rt]
                s=len(hk)
                if s>0:
                    cid = tc.get("call_id","")
                    parts=[f"工具: {name_full} ({cid})"]
                    ns=_snips(name_full,hk)
                    if ns and ns!=name_full: parts.append(f"名称命中: {ns}")
                    asnip=_snips(args_full,hk)
                    if asnip: parts.append(f"入参命中: {asnip}")
                    rs=_snips(result_full,hk)
                    if rs: parts.append(f"结果命中: {rs}")
                    if hk: parts.append(f"命中词: {', '.join(hk)}")
                    cands.append({"kind":"tc","turn_idx":tidx,"call_id":cid,"text":" | ".join(parts),"name":name_full,"args":tc.get("arguments"),"result_snip":rs or result_full[:80],"score":s})
    cands.sort(key=lambda x:-x["score"])
    return {"candidates":cands[:12]}

