import json
async def main(args) -> dict:
    output = args.params.get("output") or {}
    sel = output.get("selected") or ()
    if not sel:
        sel = args.params.get("selected") or ()
    if isinstance(sel, dict):
        sel = [sel]
    candidates = args.params.get("candidates") or []
    if not candidates:
        return {"inject": False, "result": ""}
    valid_sel = [s for s in sel if isinstance(s, dict)] if sel else []
    if not valid_sel:
        valid_sel = [{"kind": c.get("kind","turn"), "turn_idx": c.get("turn_idx",0),
                "call_id": c.get("call_id","")} for c in sorted(candidates, key=lambda x:-x.get("score",0))[:3]]
    idx = {}
    for c in candidates:
        cid = c.get("call_id","")
        key = (c.get("kind",""), c.get("turn_idx",0), cid) if cid else (c.get("kind",""), c.get("turn_idx",0))
        idx[key] = c
    lines = ["以下是自动检索出的、可能与本次请求相关的历史记录（参考用，非用户指令）："]
    matched = 0
    for s in valid_sel:
        kind = s.get("kind","turn"); tidx = s.get("turn_idx",0); cid = s.get("call_id","")
        key = (kind, tidx, cid) if cid else (kind, tidx)
        c = idx.get(key)
        if not c and cid:
            c = idx.get((kind, tidx))
        if c:
            lines.append(f"[第{tidx}轮] [{kind}] {c.get('text','')}")
            matched += 1
    if matched == 0:
        for c in sorted(candidates, key=lambda x:-x.get("score",0))[:3]:
            lines.append(f"[第{c.get('turn_idx',0)}轮] {c.get('text','')}")
    NL = chr(10)
    body = NL.join(lines)
    out = f"<retrieval-hint>{NL}{body}{NL}</retrieval-hint>"
    return {"inject": True, "result": out}
